import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { parse as parseYaml } from "yaml";
import { type Config, configSchema } from "./schema";

export const CONFIG_FILE = "harbor.yml";
/** Read when there is no harbor.yml, until 0.33. */
export const LEGACY_CONFIG_FILE = "harbor.json";

let warned = false;

export interface LoadOptions {
  warn?: (message: string) => void;
}

/** Reads harbor.yml (or, for now, harbor.json) from dir, validates it and fills in defaults. */
export function loadConfig(dir: string, opts: LoadOptions = {}): Config {
  const yml = join(dir, CONFIG_FILE);
  if (existsSync(yml)) return configSchema.parse(parseYaml(readFileSync(yml, "utf8")) ?? {});
  const json = join(dir, LEGACY_CONFIG_FILE);
  if (existsSync(json)) {
    if (!warned) {
      (opts.warn ?? console.warn)(`harbor: ${LEGACY_CONFIG_FILE} is deprecated and will not be read after 0.33; run harbor config migrate`);
      warned = true;
    }
    return configSchema.parse(JSON.parse(readFileSync(json, "utf8")));
  }
  return configSchema.parse({});
}

/** For tests. */
export function resetWarning(): void {
  warned = false;
}

