import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import type { Command } from "commander";
import { stringify } from "yaml";
import { CONFIG_FILE, LEGACY_CONFIG_FILE } from "../config/load";
import { configSchema } from "../config/schema";

export function registerConfigMigrate(program: Command): void {
  program
    .command("config")
    .description("Manage the harbor config file")
    .command("migrate")
    .description(`Write ${CONFIG_FILE} from ${LEGACY_CONFIG_FILE}`)
    .option("--force", `overwrite an existing ${CONFIG_FILE}`)
    .action((opts: { force?: boolean }) => {
      const dir = process.cwd();
      const from = join(dir, LEGACY_CONFIG_FILE);
      const to = join(dir, CONFIG_FILE);
      if (!existsSync(from)) throw new Error(`no ${LEGACY_CONFIG_FILE} here`);
      if (existsSync(to) && !opts.force) throw new Error(`${CONFIG_FILE} exists; pass --force to overwrite`);
      const raw = JSON.parse(readFileSync(from, "utf8"));
      configSchema.parse(raw); // refuse to migrate an invalid file
      writeFileSync(to, stringify(raw));
      console.log(`wrote ${CONFIG_FILE}; ${LEGACY_CONFIG_FILE} is unchanged`);
    });
}

import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { expect, test } from "vitest";
import { parse } from "yaml";
import { runCli } from "../testing/run-cli";

test("config migrate writes harbor.yml with the same values", async () => {
  const dir = mkdtempSync(join(tmpdir(), "harbor-"));
  const json = { harbour: "north", dirMode: "0700", berths: [{ id: "B1", length: 9 }] };
  writeFileSync(join(dir, "harbor.json"), JSON.stringify(json));
  await runCli(["config", "migrate"], { cwd: dir });
  expect(parse(readFileSync(join(dir, "harbor.yml"), "utf8"))).toEqual(json);
  expect(JSON.parse(readFileSync(join(dir, "harbor.json"), "utf8"))).toEqual(json);
});

test("config migrate refuses to overwrite harbor.yml", async () => {
  const dir = mkdtempSync(join(tmpdir(), "harbor-"));
  writeFileSync(join(dir, "harbor.json"), "{}");
  writeFileSync(join(dir, "harbor.yml"), "harbour: keep\n");
  await expect(runCli(["config", "migrate"], { cwd: dir })).rejects.toThrow(/exists/);
});

